mapper.select:
SELECT 
  FROM tdm03_add_title
 WHERE tdm03_person_id  = #{personId}
   AND tdm03_company_id = #{companyId}
 ORDER BY tdm03_start_date DESC
        , tdm03_add_title_nm COLLATE "ko_KR.utf8"

mapper.update:
UPDATE tdm03_add_title
   SET tdm03_add_title_nm = #{req.addTitleName}
     , tdm03_start_date   = #{req.startDate}
     , tdm03_close_date   = #{req.closeDate}
     , tdm03_upd_nm       = #{updName}
     , tdm03_upd_date     = f_sysdate()
 WHERE tdm03_add_title_id = #{req.addTitleId}
   AND tdm03_company_id   = #{companyId}

mapper.delete:
DELETE FROM tdm03_add_title
 WHERE tdm03_company_id = #{companyId}
   AND tdm03_add_title_id IN
#{id}
